input.content:
:root{
  --bg:#0b0f14;
  --panel:rgba(15,20,27,.86);
  --panel-2:rgba(25,32,41,.92);
  --line:rgba(255,255,255,.085);
  --line-strong:rgba(255,255,255,.16);
  --text:#ece6da;
  --muted:#98a1ab;
  --amber:#e8b96d;
  --amber-deep:#c58f45;
  --green:#8fbf76;
  --red:#d66f63;
  --blue:#7fb3cf;
  --shadow:0 18px 50px rgba(0,0,0,.55);
  --sat:env(safe-area-inset-top,0px);
  --sab:env(safe-area-inset-bottom,0px);
  --sal:env(safe-area-inset-left,0px);
  --sar:env(safe-area-inset-right,0px);
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;overflow:hidden;background:var(--bg);overscroll-behavior:none}
body{
  font-family:"Inter","Segoe UI",system-ui,-apple-system,Roboto,sans-serif;
  color:var(--text);
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
  user-select:none;-webkit-user-select:none;
  touch-action:none;
  -webkit-tap-highlight-color:transparent;
}
button{font-family:inherit;color:inherit;background:none;border:0;cursor:pointer;touch-action:manipulation}
svg{width:100%;height:100%;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
#game{position:fixed;inset:0;width:100%;height:100%;display:block;background:#17231a;touch-action:none}
#fx-vignette{
  position:fixed;inset:0;pointer-events:none;z-index:2;
  background:
    radial-gradient(ellipse 80% 75% at 50% 45%, transparent 55%, rgba(4,7,10,.42) 100%),
    linear-gradient(to bottom, rgba(5,8,11,.28), transparent 14%, transparent 82%, rgba(5,8,11,.4));
}
#ui{position:fixed;inset:0;z-index:3;pointer-events:none}
#ui > *{pointer-events:auto}
.hidden{display:none !important}
.glass{
  background:linear-gradient(180deg, rgba(28,35,44,.9), rgba(14,19,26,.93));
  border:1px solid var(--line);
  box-shadow:var(--shadow), inset 0 1px 0 rgba(255,255,255,.05);
  backdrop-filter:blur(14px) saturate(1.15);
  -webkit-backdrop-filter:blur(14px) saturate(1.15);
}

/* ---------- top bar ---------- */
#topbar{
  position:absolute;top:0;left:0;right:0;height:calc(58px + var(--sat));
  padding:var(--sat) max(12px, var(--sar)) 0 max(12px, var(--sal));
  display:flex;align-items:center;gap:16px;
  background:linear-gradient(180deg, rgba(8,11,15,.94), rgba(9,13,18,.78) 70%, rgba(9,13,18,0));
  z-index:20;
}
.brand{display:flex;align-items:center;gap:10px;flex:0 0 auto;padding-right:6px}
.brand-mark{width:34px;height:34px;color:var(--amber);filter:drop-shadow(0 0 10px rgba(232,185,109,.25))}
.brand-text h1{
  font-family:"Iowan Old Style","Palatino Linotype",Georgia,serif;
  font-size:17px;letter-spacing:.26em;font-weight:600;line-height:1;
  color:#f3e8d2;
}
.brand-sub{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-top:4px;display:flex;gap:6px;align-items:center}
.brand-sub .dot{opacity:.5}
#colonyName{color:var(--amber)}
.resbar{display:flex;gap:6px;flex:1 1 auto;justify-content:center;min-width:0}
.res{
  display:flex;align-items:center;gap:7px;height:34px;padding:0 11px 0 9px;
  background:rgba(255,255,255,.045);border:1px solid var(--line);border-radius:9px;
  font-size:13px;font-weight:600;font-variant-numeric:tabular-nums;letter-spacing:.02em;
  transition:background .2s, border-color .2s;
}
.res svg{width:17px;height:17px;flex:0 0 auto}
.res[data-res="wood"] svg{color:#c8935c}
.res[data-res="stone"] svg{color:#a9b0b5}
.res[data-res="food"] svg{color:#c8d47a}
.res[data-res="meal"] svg{color:#e6b566}
.res .val{min-width:20px;text-align:right}
.res.flash{animation:resflash .5s ease}
@keyframes resflash{0%{background:rgba(232,185,109,.28);border-color:rgba(232,185,109,.5)}100%{background:rgba(255,255,255,.045)}}
.top-right{display:flex;align-items:center;gap:10px;flex:0 0 auto}
.clock{display:flex;align-items:center;gap:9px;padding:0 12px;height:36px;border:1px solid var(--line);border-radius:10px;background:rgba(255,255,255,.035)}
.clock-icon{width:17px;height:17px;color:var(--amber);flex:0 0 auto}
.clock-text{display:flex;flex-direction:column;line-height:1.05}
.clock-text b{font-size:10px;letter-spacing:.14em;color:var(--muted);font-weight:600}
.clock-text span{font-size:13px;font-weight:600;font-variant-numeric:tabular-nums;margin-top:2px}
.weather{display:flex;align-items:center;gap:4px;padding-left:9px;border-left:1px solid var(--line);font-size:10.5px;letter-spacing:.03em;color:var(--muted);max-width:88px}
.weather svg{width:15px;height:15px;color:var(--blue);flex:0 0 auto}
.speeds{display:flex;align-items:center;background:rgba(255,255,255,.035);border:1px solid var(--line);border-radius:9px;padding:3px;gap:1px}
.speedbtn{
  min-width:29px;height:27px;border-radius:6px;font-size:11px;font-weight:700;color:var(--muted);
  display:grid;place-items:center;transition:.15s;font-variant-numeric:tabular-nums;
}
.speedbtn svg{width:13px;height:13px}
.speedbtn:hover{color:var(--text);background:rgba(255,255,255,.06)}
.speedbtn.active{color:#161109;background:linear-gradient(180deg,#f0c37c,#d6a04f);box-shadow:0 2px 8px rgba(214,160,79,.3)}
.iconbtn{
  width:36px;height:36px;border-radius:9px;display:grid;place-items:center;color:var(--muted);
  background:rgba(255,255,255,.035);border:1px solid var(--line);transition:.16s;
}
.iconbtn svg{width:17px;height:17px}
.iconbtn:hover{color:var(--text);background:rgba(255,255,255,.08);border-color:var(--line-strong)}
.iconbtn.ghost{background:transparent;border-color:transparent}
.iconbtn.tiny{width:22px;height:22px;border-radius:6px;position:absolute;top:4px;right:4px;background:rgba(0,0,0,.35)}
.iconbtn.tiny svg{width:11px;height:11px}

/* ---------- colonist bar ---------- */
.colonist-bar{
  position:absolute;top:calc(66px + var(--sat));left:max(12px,var(--sal));
  display:flex;gap:8px;flex-wrap:wrap;max-width:min(760px,58vw);z-index:12;
}
.colonist-chip{
  position:relative;display:flex;align-items:center;gap:9px;height:54px;padding:6px 11px 6px 6px;
  min-width:154px;border-radius:12px;cursor:pointer;
  background:linear-gradient(180deg, rgba(28,35,44,.86), rgba(13,18,24,.9));
  border:1px solid var(--line);box-shadow:0 8px 22px rgba(0,0,0,.35);
  transition:border-color .16s, transform .16s, background .16s;
  backdrop-filter:blur(10px);
}
.colonist-chip:hover{border-color:var(--line-strong);transform:translateY(-1px)}
.colonist-chip.selected{border-color:rgba(232,185,109,.65);box-shadow:0 0 0 1px rgba(232,185,109,.2),0 10px 26px rgba(0,0,0,.45)}
.avatar{
  position:relative;width:40px;height:42px;border-radius:9px;overflow:hidden;flex:0 0 auto;
  background:radial-gradient(circle at 50% 30%, #40505e, #202a33);
  border:1px solid rgba(255,255,255,.12);
}
.avatar canvas{width:100%;height:100%;display:block}
.chip-info{flex:1;min-width:0;display:flex;flex-direction:column;gap:4px}
.chip-name{font-size:11.5px;font-weight:600;letter-spacing:.02em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.chip-job{font-size:9px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mini-bars{display:flex;gap:3px;margin-top:1px}
.mbar{height:3px;border-radius:2px;background:rgba(255,255,255,.1);flex:1;overflow:hidden}
.mbar i{display:block;height:100%;border-radius:2px;transition:width .4s}
.mbar.h i{background:var(--red)}
.mbar.r i{background:var(--blue)}
.mbar.m i{background:var(--amber)}
.chip-mood{position:absolute;right:7px;top:7px;width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 7px currentColor}

/* ---------- objectives ---------- */
.objectives{
  position:absolute;top:calc(66px + var(--sat));right:max(12px,var(--sar));width:238px;border-radius:13px;
  padding:11px 13px 9px;z-index:11;
}
.obj-head{display:flex;justify-content:space-between;align-items:center;font-size:9px;letter-spacing:.16em;color:var(--muted);margin-bottom:8px}
.obj-head span:last-child{color:var(--amber);font-weight:700;letter-spacing:.06em}
.obj-row{display:flex;align-items:flex-start;gap:8px;padding:4px 0;font-size:11px;line-height:1.35;color:#c6cbd2}
.obj-row .tick{width:13px;height:13px;border-radius:4px;border:1px solid rgba(255,255,255,.22);flex:0 0 auto;margin-top:1px;display:grid;place-items:center}
.obj-row .tick svg{width:9px;height:9px;stroke-width:2.6;color:#111;opacity:0}
.obj-row.done .tick{background:var(--green);border-color:var(--green)}
.obj-row.done .tick svg{opacity:1}
.obj-row.done .txt{color:#6f7a70;text-decoration:line-through}
.obj-row .txt{flex:1}

/* ---------- raid banner ---------- */
.raid-banner{
  position:absolute;top:calc(62px + var(--sat));left:50%;transform:translateX(-50%);
  display:flex;align-items:center;gap:11px;padding:8px 10px 8px 12px;border-radius:12px;
  background:linear-gradient(180deg, rgba(66,24,24,.94), rgba(34,13,14,.95));
  border:1px solid rgba(214,111,99,.5);box-shadow:0 10px 40px rgba(120,20,20,.35);
  z-index:22;animation:bannerIn .35s cubic-bezier(.2,.9,.2,1);
}
@keyframes bannerIn{from{opacity:0;transform:translate(-50%,-12px)}to{opacity:1;transform:translate(-50%,0)}}
.rb-icon{width:30px;height:30px;border-radius:8px;display:grid;place-items:center;background:rgba(214,111,99,.18);color:#f0a096;flex:0 0 auto}
.rb-icon svg{width:17px;height:17px}
.rb-text{display:flex;flex-direction:column;min-width:0}
.rb-text b{font-size:11.5px;letter-spacing:.05em}
.rb-text span{font-size:10px;color:#caa3a0;margin-top:1px;white-space:nowrap}
.btn{
  height:36px;padding:0 15px;border-radius:9px;border:1px solid var(--line-strong);
  font-size:11px;font-weight:700;letter-spacing:.09em;display:inline-flex;align-items:center;gap:7px;justify-content:center;
  transition:.16s;color:var(--text);background:rgba(255,255,255,.05);
}
.btn:hover{background:rgba(255,255,255,.09)}
.btn.small{height:29px;padding:0 11px;font-size:9.5px;border-radius:7px}
.btn.big{height:48px;padding:0 28px;font-size:12px;letter-spacing:.16em;border-radius:11px}
.btn.primary{background:linear-gradient(180deg,#f2c67e,#c99446);color:#191207;border-color:rgba(255,220,160,.5);box-shadow:0 8px 26px rgba(201,148,70,.28)}
.btn.primary:hover{filter:brightness(1.07)}
.btn.danger{background:rgba(214,111,99,.16);border-color:rgba(214,111,99,.45);color:#f3aca3}
.btn.danger:hover{background:rgba(214,111,99,.28)}
.btn.ghost{background:transparent;border-color:var(--line)}
.btn.ghost:hover{background:rgba(255,255,255,.06)}
.btn:disabled{opacity:.42;cursor:not-allowed}

/* ---------- toasts ---------- */
.toasts{position:absolute;top:calc(120px + var(--sat));left:50%;transform:translateX(-50%);display:flex;flex-direction:column;gap:7px;z-index:25;width:min(420px,calc(100vw - 30px));pointer-events:none}
.toast{
  display:flex;align-items:center;gap:9px;padding:8px 12px;border-radius:9px;font-size:11.5px;line-height:1.35;
  background:rgba(14,19,26,.93);border:1px solid var(--line);box-shadow:0 10px 30px rgba(0,0,0,.4);
  animation:toastIn .28s cubic-bezier(.2,.9,.2,1);color:#d9d4c8;
}
.toast.out{animation:toastOut .35s ease forwards}
@keyframes toastIn{from{opacity:0;transform:translateY(-8px) scale(.98)}to{opacity:1;transform:none}}
@keyframes toastOut{to{opacity:0;transform:translateY(-6px)}}
.toast .tico{width:7px;height:7px;border-radius:50%;background:var(--amber);flex:0 0 auto;box-shadow:0 0 8px currentColor}
.toast.good .tico{background:var(--green)}
.toast.warn .tico{background:var(--amber)}
.toast.bad .tico{background:var(--red)}
.toast b{font-weight:700;color:#f2ecdf}

/* ---------- toolbar ---------- */
.toolbar{
  position:absolute;bottom:calc(14px + var(--sab));left:50%;transform:translateX(-50%);
  display:flex;align-items:stretch;gap:3px;padding:5px;border-radius:15px;
  background:linear-gradient(180deg, rgba(29,36,45,.92), rgba(12,17,23,.95));
  border:1px solid var(--line);box-shadow:var(--shadow);backdrop-filter:blur(16px);
  z-index:30;
}
.tool{
  position:relative;width:68px;height:56px;border-radius:11px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;
  color:var(--muted);transition:.16s;border:1px solid transparent;
}
.tool .ticon{width:23px;height:23px}
.tool .ticon svg{stroke-width:1.65}
.tool .tlabel{font-size:8.5px;letter-spacing:.1em;text-transform:uppercase;font-weight:600}
.tool:hover{color:var(--text);background:rgba(255,255,255,.055)}
.tool.active{color:#f4d49b;background:linear-gradient(180deg,rgba(232,185,109,.16),rgba(232,185,109,.07));border-color:rgba(232,185,109,.28)}
.tool.active::after{content:"";position:absolute;bottom:3px;width:16px;height:2px;border-radius:2px;background:var(--amber);box-shadow:0 0 8px rgba(232,185,109,.6)}

/* ---------- drawer ---------- */
.drawer{
  position:absolute;bottom:calc(84px + var(--sab));left:50%;transform:translateX(-50%);
  width:min(740px,calc(100vw - 24px));max-height:min(430px,48vh);
  background:linear-gradient(180deg, rgba(24,31,40,.96), rgba(11,15,21,.97));
  border:1px solid var(--line-strong);border-radius:16px;box-shadow:var(--shadow);
  z-index:29;display:flex;flex-direction:column;overflow:hidden;
  animation:drawerIn .24s cubic-bezier(.2,.9,.2,1);backdrop-filter:blur(18px);
}
@keyframes drawerIn{from{opacity:0;transform:translate(-50%,14px)}to{opacity:1;transform:translate(-50%,0)}}
.drawer-grip{height:3px;width:40px;border-radius:3px;background:rgba(255,255,255,.18);margin:7px auto 0;flex:0 0 auto}
.drawer-head{display:flex;justify-content:space-between;align-items:flex-start;padding:10px 16px 8px;flex:0 0 auto}
.drawer-head h2{font-family:"Iowan Old Style","Palatino Linotype",Georgia,serif;font-size:19px;letter-spacing:.08em;font-weight:600;color:#f0e7d6}
.drawer-head p{font-size:10.5px;color:var(--muted);margin-top:2px}
.drawer-body{padding:2px 14px 12px;overflow-y:auto;overflow-x:hidden;-webkit-overflow-scrolling:touch;touch-action:pan-y;overscroll-behavior:contain}
.drawer-body::-webkit-scrollbar{width:6px}
.drawer-body::-webkit-scrollbar-thumb{background:rgba(255,255,255,.14);border-radius:3px}
.drawer-foot{padding:0 14px 12px;flex:0 0 auto}
.cat-tabs{display:flex;gap:5px;margin-bottom:10px;flex-wrap:wrap}
.cat-tab{padding:5px 12px;border-radius:7px;font-size:10px;letter-spacing:.08em;text-transform:uppercase;font-weight:600;color:var(--muted);border:1px solid var(--line);transition:.15s}
.cat-tab.active{color:#f0d3a0;background:rgba(232,185,109,.12);border-color:rgba(232,185,109,.3)}
.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(142px,1fr));gap:7px}
.build-card{
  display:flex;gap:9px;align-items:center;padding:8px;border-radius:10px;text-align:left;
  background:rgba(255,255,255,.035);border:1px solid var(--line);transition:.15s;position:relative;
}
.build-card:hover{background:rgba(255,255,255,.075);border-color:var(--line-strong);transform:translateY(-1px)}
.build-card.active{border-color:rgba(232,185,109,.6);background:rgba(232,185,109,.1)}
.build-card.disabled{opacity:.45}
.bc-ic{width:40px;height:40px;border-radius:8px;display:grid;place-items:center;flex:0 0 auto;background:rgba(0,0,0,.28);border:1px solid var(--line)}
.bc-ic svg{width:24px;height:24px;stroke-width:1.4;color:#d8cfbf}
.bc-body{min-width:0;flex:1}
.bc-name{font-size:11px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bc-cost{display:flex;gap:7px;margin-top:3px;font-size:9px;color:var(--muted);flex-wrap:wrap}
.bc-cost span{display:flex;align-items:center;gap:2px}
.bc-cost svg{width:9px;height:9px}
.bc-key{position:absolute;top:5px;right:6px;font-size:8px;color:#6c767f;letter-spacing:.05em}

.zone-card{display:flex;gap:11px;align-items:flex-start;padding:10px;border-radius:10px;background:rgba(255,255,255,.035);border:1px solid var(--line);text-align:left;transition:.15s}
.zone-card:hover{background:rgba(255,255,255,.07)}
.zone-card.active{border-color:rgba(232,185,109,.55);background:rgba(232,185,109,.09)}
.zc-swatch{width:38px;height:38px;border-radius:8px;flex:0 0 auto;border:1px solid rgba(255,255,255,.18)}
.zc-swatch.stock{background:repeating-linear-gradient(45deg,rgba(232,185,109,.3),rgba(232,185,109,.3) 4px,rgba(232,185,109,.12) 4px,rgba(232,185,109,.12) 8px)}
.zc-swatch.farm{background:repeating-linear-gradient(90deg,#5a4329,#5a4329 5px,#6b5132 5px,#6b5132 10px)}
.zc-swatch.erase{background:repeating-linear-gradient(45deg,rgba(214,111,99,.35),rgba(214,111,99,.35) 4px,rgba(214,111,99,.1) 4px,rgba(214,111,99,.1) 8px)}
.zc-body b{font-size:11.5px;display:block}
.zc-body span{font-size:9.5px;color:var(--muted);line-height:1.35;display:block;margin-top:2px}

.order-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:7px}
.order-card{display:flex;align-items:center;gap:10px;padding:10px;border-radius:10px;background:rgba(255,255,255,.035);border:1px solid var(--line);text-align:left;transition:.15s}
.order-card:hover{background:rgba(255,255,255,.07)}
.order-card.active{border-color:rgba(232,185,109,.55);background:rgba(232,185,109,.09)}
.oc-ic{width:34px;height:34px;border-radius:8px;display:grid;place-items:center;background:rgba(0,0,0,.25);border:1px solid var(--line);flex:0 0 auto;color:#d8cfbf}
.oc-ic svg{width:18px;height:18px}
.order-card b{font-size:11.5px;display:block}
.order-card span{font-size:9.5px;color:var(--muted);display:block;margin-top:1px}

.research-row{display:flex;gap:10px;align-items:center;padding:10px;border-radius:10px;background:rgba(255,255,255,.03);border:1px solid var(--line);margin-bottom:7px}
.research-row.active{border-color:rgba(127,179,207,.4);background:rgba(127,179,207,.08)}
.research-row.done{opacity:.62}
.rr-ic{width:38px;height:38px;border-radius:9px;background:rgba(127,179,207,.1);display:grid;place-items:center;color:var(--blue);flex:0 0 auto;border:1px solid rgba(127,179,207,.2)}
.rr-ic svg{width:20px;height:20px}
.rr-body{flex:1;min-width:0}
.rr-body b{font-size:11.5px;display:flex;align-items:center;gap:7px}
.rr-body p{font-size:9.5px;color:var(--muted);margin-top:2px;line-height:1.35}
.rr-prog{height:3px;border-radius:2px;background:rgba(255,255,255,.08);margin-top:6px;overflow:hidden}
.rr-prog i{display:block;height:100%;background:linear-gradient(90deg,#6f9fbb,#a8d0e2);border-radius:2px;transition:width .3s}
.rr-btn{flex:0 0 auto}
.research-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px;font-size:10px;color:var(--muted);letter-spacing:.08em;text-transform:uppercase}
.research-head b{color:var(--blue);font-size:11px;letter-spacing:.04em}

/* ---------- selection ---------- */
.selection{
  position:absolute;bottom:calc(88px + var(--sab));left:max(12px,var(--sal));width:304px;border-radius:14px;
  padding:12px;z-index:24;animation:selIn .2s ease;
}
@keyframes selIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.sel-head{display:flex;gap:10px;align-items:center;position:relative}
.sel-avatar{width:52px;height:56px;border-radius:10px;overflow:hidden;background:#202a33;border:1px solid rgba(255,255,255,.15);flex:0 0 auto}
.sel-avatar canvas{width:100%;height:100%;display:block}
.sel-title{flex:1;min-width:0}
.sel-title b{font-size:14px;letter-spacing:.02em;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sel-title span{font-size:9px;letter-spacing:.12em;text-transform:uppercase;color:var(--amber);display:block;margin-top:2px}
.sel-close{position:absolute;top:-4px;right:-4px;width:24px;height:24px}
.sel-close svg{width:11px;height:11px}
.sel-needs{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:11px}
.need{background:rgba(255,255,255,.03);border:1px solid var(--line);border-radius:7px;padding:5px 7px}
.need .nlabel{display:flex;justify-content:space-between;font-size:8px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:3px}
